(()=>{const id='mflow-network-status';let timer;function banner(){let el=document.getElementById(id);if(el)return el;el=document.createElement('div');el.id=id;el.className='mflow-network-status';el.setAttribute('role','status');el.setAttribute('aria-live','polite');el.hidden=true;document.body.appendChild(el);return el}function update(event){const el=banner();clearTimeout(timer);if(!navigator.onLine){el.textContent='Jste offline. Nové změny se teď neuloží.';el.className='mflow-network-status is-offline';el.hidden=false;return}if(event&&event.type==='online'){el.textContent='Připojení je zpět.';el.className='mflow-network-status is-online';el.hidden=false;timer=setTimeout(()=>{el.hidden=true},3000);return}el.hidden=true}function start(){update();addEventListener('online',update);addEventListener('offline',update)}if(document.readyState==='loading')addEventListener('DOMContentLoaded',start,{once:true});else start()})();
